/**
 * Creates a debounce function that delays invoking the callback until after
 * the specified delay (in milliseconds) has passed since the last time the
 * returned function was invoked.
 *
 * @param {Function} callback - The function to debounce.
 * @param {number} delay - The number of milliseconds to delay.
 * @returns {Function} - A new debounced function.
 */
function debounce(callback, delay) {
  let timeoutId;

  return function (...args) {
    // Clear the previous timer if the function is called again
    clearTimeout(timeoutId);

    // Set a new timer to invoke the callback after the delay
    timeoutId = setTimeout(() => {
      callback.apply(this, args);
    }, delay);
  };
}

