/**
 * Creates a debounced function that delays invoking `callback` until after `delay` milliseconds
 * have passed since the last time the debounced function was invoked.
 *
 * If the debounced function is called again within the delay period, the timer is reset,
 * and the callback will only execute after the full delay has passed since the *last* invocation.
 *
 * @param {Function} callback The function to debounce. This function will receive the `this` context
 *                            and arguments from the last invocation of the debounced function.
 * @param {number} delay The number of milliseconds to delay.
 * @returns {Function} A new, debounced version of the provided function.
 */
function debounce(callback, delay) {
  let timeoutId; // This variable will hold the ID of the timer

  // Return a new function that will be the debounced version
  return function(...args) {
    // Preserve the `this` context from the original call site
    const context = this;

    // Clear any existing timer to reset the debounce period
    clearTimeout(timeoutId);

    // Set a new timer
    timeoutId = setTimeout(() => {
      // After the delay, invoke the original callback with the correct context and arguments
      callback.apply(context, args);
    }, delay);
  };
}

