 * have passed since the last time the debounced function was invoked.
 *
 * If the debounced function is called again before the timer is up, the timer is reset.
 *
 * @param {Function} callback The function to debounce.
 * @param {number} delay The number of milliseconds to delay.
 * @returns {Function} A new, debounced function.
 */
function debounce(callback, delay) {
  let timeoutId; // This will hold the ID of the timeout, allowing us to clear it.

  // Return a new function that will be the debounced version of the original callback.
  // This function uses rest parameters `...args` to capture all arguments passed to it,
  // and `this` to capture the execution context.
  return function(...args) {
    const context = this; // Capture the 'this' context from the current invocation.

    // Clear any existing timeout to reset the timer.
    // This ensures that the callback only fires after the delay has truly passed
    // since the *last* invocation.
    clearTimeout(timeoutId);

    // Set a new timeout. When it expires, the original callback will be invoked.
    timeoutId = setTimeout(() => {
      // Use `apply` to invoke the original callback, ensuring:
      // 1. The captured 'this' context is correctly passed.
      // 2. All captured arguments are correctly passed as an array.
      callback.apply(context, args);
    }, delay);
  };
}

