def validate_email(email):
    # Check if input is a string
    if not isinstance(email, str):
        return False

    # Check for spaces in the email
    if ' ' in email:
        return False

    # Check for exactly one @ symbol
    if email.count('@') != 1:
        return False

    # Split the email into local part and domain part
    local_part, domain = email.split('@')

    # Ensure both local part and domain are non-empty
    if not local_part or not domain:
        return False

    # Check if domain contains at least one dot
    if '.' not in domain:
        return False

    # Ensure domain doesn't start or end with a dot
    if domain.startswith('.') or domain.endswith('.'):
        return False

    # Ensure no consecutive dots in domain and no dot right after @
    if '..' in domain:
        return False

    # Split domain by dots to check each segment
    domain_parts = domain.split('.')

    # All domain parts must be non-empty
    if any(not part for part in domain_parts):
        return False

    return True

